const body = $json.body ?? $json;
const key = String(body.idempotencyKey ?? '');
if (!key || key.length < 8) return [{ json: { ok: false, status: 400, reason: 'idempotency_key_required' } }];
const attempt = Math.max(1, Math.min(3, Number(body.attempt ?? 1)));
const simulated = body.simulatedResult === 'success' ? 'success' : 'transient_failure';
return [{ json: { ok: simulated === 'success', route: simulated === 'success' ? 'success' : (attempt < 3 ? 'retry' : 'recovery'), status: simulated === 'success' ? 200 : 503, idempotencyKey: key, attempt, maxAttempts: 3, simulatedResult: simulated, retryable: simulated !== 'success' && attempt < 3 } }];
